example.source:
deepml specialized 0.3
module corpus.deepml_specialized.example_01751
policy deterministic
policy no_network
domain finance {
  unit InputUnit = base("input")
  tensor x: f64<InputUnit>[1,4]
  operator value_at_risk(x) -> Tensor pure deterministic
  calibration C01751 { method: bounded_least_squares tolerance: 1e-6 }
  constraint PhysicalBounds { min: 0 max: 951 }
  validate x with [value_at_risk, C01751, PhysicalBounds]
}
assert domain.semantic_hash == "invalid-01751"

